tools.example:
t = (0:0.01:10)'; u = sin(2*pi*t);
inData = timeseries(u, t);
add_block('simulink/Sources/From Workspace', 'mdl/Replay');
set_param('mdl/Replay', 'VariableName', 'inData', 'SampleTime', '0.01', 'Interpolate', 'on');

add_block('simulink/Sources/From File', 'mdl/Log');
set_param('mdl/Log', 'FileName', 'drivecycle.mat', ...
    'InterpolationWithinTimeRange', 'Zero order hold', ...
    'ExtrapolationAfterLastDataPoint', 'Hold last value');
